   ['శాకాహారి', 'Herbivore'], ['మాంసాహారి', 'Carnivore'], ['సర్వాహారి', 'Omnivore'], ['విచ్ఛిన్నకారులు / పూతికాహారులు', 'Decomposers / Saprotrophs'], ['ఆహార గొలుసు', 'Food chain'],
   ['ఆహార జాలం', 'Food web'], ['పోషక స్థాయి', 'Trophic level'], ['నిశాచరాలు', 'Nocturnal animals'], ['పరాగసంపర్కం', 'Pollination'], ['సహజీవనం', 'Mutualism'], ['సహభోజిత్వం', 'Commensalism'],
